INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 5, 52, '', '[2017 KPSS Çıkmış Soru]

Lozan Konferansı\'na katılan devletler hakkında aşağıdaki bilgiler verilmiştir:  Çağrı yapan devletler: İngiltere, Fransa, İtalya, Japonya  Tüm görüşmelere çağrılan devletler: Türkiye, Yunanistan, Romanya, Sırp-Hırvat-Sloven Devleti (Yugoslavya)  Gözlemci devlet: ABD  Boğazlar statüsü için çağrılan Karadeniz\'e kıyısı olan devletler: Sovyet Rusya, Bulgaristan  Ticaret ve yerleşme sözleşmelerine katılmak için çağrılanlar: Belçika, Portekiz Konferansa katılan devletler ve katılım konuları göz önüne alındığında aşağıdakilerden hangisine ulaşılamaz?', 1, 'Lozan Konferansı\'nın toplanması için davet Anlaşma Devletlerinden gelmiştir.', 'Türkiye\'nin ve bazı Balkan devletlerinin görüşmelerin hepsinde yer alması istenmiştir.', 'Konferans görüşmelerine Avrupa kıtası dışından da devletler davet edilmiştir.', 'Boğazlar konusunda yapılacak görüşmelere çağrılan devletlerin belirlenmesinde ülkelerin coğrafi konumları da etkili olmuştur.', 'Lozan Konferansı\'nda uluslararası ticaret ile ilgili kuralları Belçika ve Portekiz belirlemiştir.', 'e', 1, '2017 KPSS Lisans Genel Kültür oturumunda ÖSYM tarafından sorulmuş orijinal çıkmış sınav sorusudur.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 5, 52, '', '[2017 KPSS Çıkmış Soru]

