INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (3, 14, 52, '', '[2009 KPSS Çıkmış Soru]

1982 Anayasası’na göre, TBMM’nin seçim dönemi ile ilgili aşağıdaki ifadelerden hangisi doğrudur?', 1, '2007 yılında gerçekleştirilen Anayasa değişikliği uyarınca TBMM seçimleri 5 yılda bir yapılır.', 'Meclis, seçim dönemi dolmadan üye tam sayısı- nın en az salt çoğunluğunun oyu ile erken seçim kararı alabilir.', 'Meclisin, seçim dönemi dolmadan erken seçim kararı alması üzerine yapılan seçime ara seçim denir.', 'Cumhurbaşkanı, ülkenin herhangi bir nedenle siyasi bunalıma girdiğini düşündüğü her durum- da, bu bunalımı çözme amacıyla TBMM seçim- lerinin yenilenmesine karar verebilir.', 'TBMM Genel Kurulu veya Cumhurbaşkanı tara- fından yenilenmesine karar verilen Meclisin yet- kileri, yeni Meclisin seçilmesine kadar devam eder.', 'e', 1, '2009 KPSS Lisans Genel Kültür oturumunda ÖSYM tarafından sorulmuş orijinal çıkmış sınav sorusudur.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (3, 15, 52, '', '[2009 KPSS Çıkmış Soru]

