INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (3, 14, 52, '', '[2009 KPSS Çıkmış Soru]

1982 Anayasası’nın değiştirilmesi ile ilgili aşağı- daki ifadelerden hangisi yanlıştır?', 1, 'Anayasa’nın değiştirilmesi, TBMM üye tam sayı- sının en az üçte biri yazıyla teklif edi- lebilir.', 'TBMM Genel Kurulu, Anayasa değişikliğine iliş- kin kanunların kabulü sırasında, bu kanunun halkoyuna sunulması hâlinde, Anayasa’nın de- ğiştirilen hükümlerinden hangilerinin birlikte, han- gilerinin ayrı ayrı oylanacağını da karara bağlar.', 'Anayasa’nın değiştirilmesi hakkındaki tekliflerin kabulü, Meclisin üye tam sayısının en az beşte üç çoğunluğunun gizli oyuyla mümkün olabilir.', 'TBMM Genel Kurulu üye tam sayısı- nın en az üçte iki çoğunluğu ile kabul edilen bir Anayasa değişikliğini, Cumhurbaşkanı dilerse halkoyuna sunabilir, dilerse yürürlüğe girmesi için Resmî Gazete’de yayımlanmasına karar verebilir.', 'TBMM Genel Kurulu acil hâllerde Anayasa de- ğişikliğine ilişkin tekliflerin bir kez oylanmasının yeterli olacağına karar verebilir. Ancak, böyle bir kararın alınabilmesi, TBMM üye tam sayısının en az üçte iki çoğunluğunun oyu ile mümkün olabilir.', 'e', 1, '2009 KPSS Lisans Genel Kültür oturumunda ÖSYM tarafından sorulmuş orijinal çıkmış sınav sorusudur.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (3, 17, 52, '', '[2009 KPSS Çıkmış Soru]

